<?php
declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';$pageTitle='Movie & Drama';
$filter=(string)($_GET['status_filter']??'All');$allowed=['All','Watching','Completed','Plan to Watch'];if(!in_array($filter,$allowed,true))$filter='All';$category=(string)($_GET['category']??'All');$categories=['All','Movie','Drama','Anime','Series','Documentary','Other'];if(!in_array($category,$categories,true))$category='All';$search=trim((string)($_GET['q']??''));
$counts=$pdo->query("SELECT COUNT(*) total, SUM(watch_status='Watching') watching, SUM(watch_status='Completed') completed, SUM(watch_status='Plan to Watch') planned FROM media_watchlist")->fetch()?:[];
$sql='SELECT * FROM media_watchlist';$where=[];$args=[];if($filter!=='All'){$where[]='watch_status=?';$args[]=$filter;}if($category!=='All'){$where[]='media_type=?';$args[]=$category;}if($search!==''){$where[]='(title LIKE ? OR genre LIKE ?)';$args[]='%'.$search.'%';$args[]='%'.$search.'%';}if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=" ORDER BY FIELD(watch_status,'Watching','Plan to Watch','Completed'), updated_at DESC, title ASC";$q=$pdo->prepare($sql);$q->execute($args);$items=$q->fetchAll();
$monthStart = new DateTimeImmutable('first day of this month');
$chartTypes = ['Movie' => 'movie', 'Drama' => 'drama', 'Documentary' => 'documentary', 'Anime' => 'anime', 'Series' => 'series', 'Other' => 'other'];
$chartMonths = [];
for ($i = 5; $i >= 0; $i--) {
    $month = $monthStart->modify("-{$i} months");
    $key = $month->format('Y-m');
    $chartMonths[$key] = ['label' => $month->format('M')];
    foreach ($chartTypes as $slug) $chartMonths[$key][$slug] = 0;
}
$chartQuery = $pdo->prepare("SELECT DATE_FORMAT(completed_at, '%Y-%m') AS month_key, media_type, COUNT(*) AS total
 FROM media_watchlist
 WHERE watch_status = 'Completed' AND completed_at >= ? AND completed_at < ?
 GROUP BY month_key, media_type ORDER BY month_key");
$chartQuery->execute([$monthStart->modify('-5 months')->format('Y-m-01 00:00:00'), $monthStart->modify('+1 month')->format('Y-m-01 00:00:00')]);
foreach ($chartQuery->fetchAll() as $row) {
    if (isset($chartMonths[$row['month_key']]) && isset($chartTypes[$row['media_type']])) {
        $chartMonths[$row['month_key']][$chartTypes[$row['media_type']]] = (int)$row['total'];
    }
}
$chartMax = 1;
foreach ($chartMonths as $monthData) foreach ($chartTypes as $slug) $chartMax = max($chartMax, $monthData[$slug]);
include __DIR__.'/../includes/header.php';?>
