<section class="media-stats"><article class="stat-card"><div class="stat-top"><span class="stat-icon">▣</span><span class="stat-label">TOTAL TITLES</span></div><div class="stat-value"><?= (int)($counts['total']??0) ?><span class="stat-unit"> saved</span></div><div class="stat-foot">Your personal collection</div></article><article class="stat-card"><div class="stat-top"><span class="stat-icon">◉</span><span class="stat-label">WATCHING</span></div><div class="stat-value"><?= (int)($counts['watching']??0) ?></div><div class="stat-foot">Currently in progress</div></article><article class="stat-card"><div class="stat-top"><span class="stat-icon">✦</span><span class="stat-label">COMPLETED</span></div><div class="stat-value"><?= (int)($counts['completed']??0) ?></div><div class="stat-foot">Stories you've finished</div></article><article class="stat-card"><div class="stat-top"><span class="stat-icon">⌁</span><span class="stat-label">PLAN TO WATCH</span></div><div class="stat-value"><?= (int)($counts['planned']??0) ?></div><div class="stat-foot">For another day</div></article></section>
<section class="panel monthly-chart-panel">
  <div class="media-toolbar"><div><p class="eyebrow">YOUR WATCHING HABITS</p><h2>Monthly viewing comparison</h2><p class="muted">Completed titles by category · last 6 months</p></div></div>
  <div class="chart-legend">
    <?php foreach ($chartTypes as $label => $slug): ?><span><i class="legend-dot legend-<?=e($slug)?>"></i><?=e($label)?></span><?php endforeach; ?>
  </div>
  <div class="monthly-chart" role="group" aria-label="Monthly comparison of completed titles by category for the last six months">
  <?php foreach ($chartMonths as $monthKey => $monthData): $monthTotal=0; foreach ($chartTypes as $slug) $monthTotal += $monthData[$slug]; ?>
    <div class="chart-month">
      <div class="chart-bars">
        <?php foreach ($chartTypes as $label => $slug): $quantity=(int)$monthData[$slug]; ?>
          <div class="chart-bar-group">
            <div class="chart-bar chart-bar-<?=e($slug)?>" style="height:<?=max(2, (int)round($quantity / $chartMax * 100))?>%" tabindex="0" role="img" aria-label="<?=e($label)?> quantities: <?=$quantity?> in <?=e($monthData['label'])?>" data-tooltip="<?=e($label)?> quantities: <?=$quantity?>" title="<?=e($label)?> quantities: <?=$quantity?>"></div>
          </div>
        <?php endforeach; ?>
      </div>
      <span class="chart-month-label"><?=e($monthData['label'])?></span><span class="chart-month-total"><?=$monthTotal?> completed</span>
    </div>
  <?php endforeach; ?>
  </div>
  <p class="chart-note">Hover over or focus a bar to see its category count. A title is counted in the month it was marked Completed.</p>
</section>
