HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP))?>'>✎ Edit</button><form method="post" action="../actions/media-remove.php" data-confirm="Remove this title from your watchlist? The saved poster will also be removed."><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button type="submit" class="btn btn-danger-outline btn-small">× Remove</button></form></div></div></article><?php endforeach;?></div><?php endif;?></section>
